<script setup>
import { computed,onMounted,ref } from "vue";
import { confirmAction } from "../../services/alert.service.js";
import { createPlatformStaff,getPlatformAudit,getPlatformStaff,platformLogin,platformLogout,resetPlatformStaffPassword,updatePlatformStaff } from "../../services/platform-admin.service.js";
const token=ref(localStorage.getItem("platform_staff_token"));const me=ref(JSON.parse(localStorage.getItem("platform_staff")||"null"));const staff=ref([]);const audit=ref([]);const tab=ref("staff");const loading=ref(false);const saving=ref(false);const showForm=ref(false);const formMode=ref("create");const editing=ref(null);const showPassword=ref(false);const credentials=ref({email:"",password:""});const form=ref({name:"",email:"",password:"",role:"support",is_active:true});
const isSuper=computed(()=>me.value?.role==="super_admin");const activeCount=computed(()=>staff.value.filter(x=>x.is_active).length);const roles=["super_admin","operations","support","billing"];const roleName=r=>({super_admin:"Super Admin",operations:"Operations",support:"Support",billing:"Billing"}[r]||r);const date=v=>v?new Date(v).toLocaleString():"Never";
const load=async()=>{if(!token.value)return;loading.value=true;try{const [s,a]=await Promise.all([getPlatformStaff(),getPlatformAudit()]);staff.value=s.data.data;audit.value=a.data.data;}finally{loading.value=false;}};
const signIn=async()=>{saving.value=true;try{const response=await platformLogin(credentials.value);token.value=response.data.token;me.value=response.data.staff;localStorage.setItem("platform_staff_token",token.value);localStorage.setItem("platform_staff",JSON.stringify(me.value));await load();}finally{saving.value=false;}};
const signOut=async()=>{try{await platformLogout();}finally{localStorage.removeItem("platform_staff_token");localStorage.removeItem("platform_staff");token.value=null;me.value=null;}};
const openCreate=()=>{formMode.value="create";editing.value=null;form.value={name:"",email:"",password:"",role:"support",is_active:true};showForm.value=true;};
const openEdit=item=>{formMode.value="edit";editing.value=item;form.value={name:item.name,email:item.email,password:"",role:item.role,is_active:item.is_active};showForm.value=true;};
const save=async()=>{saving.value=true;try{if(formMode.value==="password"){const ok=await confirmAction({title:`Reset ${editing.value.name}'s password?`,text:"All existing sessions for this staff member will be ended.",confirmText:"Reset password",danger:true});if(!ok)return;await resetPlatformStaffPassword(editing.value.id,form.value.password);}else if(editing.value)await updatePlatformStaff(editing.value.id,{name:form.value.name,role:form.value.role,is_active:form.value.is_active});else await createPlatformStaff(form.value);showForm.value=false;await load();}finally{saving.value=false;}};
const resetPassword=item=>{formMode.value="password";editing.value=item;form.value={...form.value,password:""};showForm.value=true;};
onMounted(load);window.addEventListener("platform-session-expired",()=>{token.value=null;me.value=null;});
</script>
<template>
<main v-if="!token" class="platform-login"><section><a class="brand" href="/"><span>V</span><div><strong>Vikoba Control</strong><small>Platform administration</small></div></a><div class="login-copy"><span>Restricted area</span><h1>Staff admin panel</h1><p>Sign in with an authorized platform staff account. Group administrator accounts cannot access this area.</p></div><form @submit.prevent="signIn"><label>Email address<input v-model.trim="credentials.email" type="email" autocomplete="username" required></label><label>Password<div><input v-model="credentials.password" :type="showPassword?'text':'password'" autocomplete="current-password" required><button type="button" @click="showPassword=!showPassword"><i class="bi" :class="showPassword?'bi-eye-slash':'bi-eye'"></i></button></div></label><button class="primary" :disabled="saving">{{ saving?'Signing in...':'Open admin panel' }}</button></form><a class="back" href="/">← Return to website</a></section><aside><i class="bi bi-shield-lock"></i><h2>Protected platform operations.</h2><p>Separate authentication, role controls, revoked sessions, and a permanent staff activity trail keep system administration isolated from VICOBA workspaces.</p></aside></main>
<div v-else class="platform-shell"><aside class="rail"><div class="rail-brand"><span>V</span><div><strong>Vikoba</strong><small>Control center</small></div></div><nav><button :class="{active:tab==='staff'}" @click="tab='staff'"><i class="bi bi-people"></i>Staff</button><button :class="{active:tab==='audit'}" @click="tab='audit'"><i class="bi bi-clock-history"></i>Activity</button><a href="/dashboard"><i class="bi bi-box-arrow-up-right"></i>Group app</a></nav><div class="account"><strong>{{ me.name }}</strong><small>{{ roleName(me.role) }}</small><button @click="signOut"><i class="bi bi-box-arrow-right"></i> Sign out</button></div></aside><section class="workspace"><header><div><small>PLATFORM ADMINISTRATION</small><h1>{{ tab==='staff'?'Staff management':'Staff activity' }}</h1></div><button v-if="tab==='staff'&&isSuper" class="primary" @click="openCreate"><i class="bi bi-plus-lg"></i>Add staff</button></header><div v-if="tab==='staff'" class="content"><section class="metrics"><article><span>Total staff</span><strong>{{ staff.length }}</strong></article><article><span>Active</span><strong>{{ activeCount }}</strong></article><article><span>Roles assigned</span><strong>{{ new Set(staff.map(x=>x.role)).size }}</strong></article></section><section class="panel"><div class="panel-title"><div><h2>Application staff</h2><p>People authorized to operate the Vikoba platform.</p></div><span>{{ activeCount }} active</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Staff member</th><th>Role</th><th>Status</th><th>Last sign-in</th><th></th></tr></thead><tbody><tr v-for="item in staff" :key="item.id"><td><div class="person"><span>{{ item.name[0] }}</span><div><strong>{{ item.name }}</strong><small>{{ item.email }}</small></div></div></td><td><span class="role">{{ roleName(item.role) }}</span></td><td><span class="status" :class="{off:!item.is_active}">{{ item.is_active?'Active':'Deactivated' }}</span></td><td>{{ date(item.last_login_at) }}</td><td><div v-if="isSuper" class="actions"><button @click="openEdit(item)"><i class="bi bi-pencil"></i></button><button @click="resetPassword(item)"><i class="bi bi-key"></i></button></div></td></tr></tbody></table></div></section></div><div v-else class="content"><section class="panel"><div class="panel-title"><div><h2>Security activity</h2><p>Latest administrative changes to staff accounts.</p></div></div><div class="audit-list"><article v-for="event in audit" :key="event.id"><i class="bi bi-shield-check"></i><div><strong>{{ event.action.replaceAll('_',' ') }}</strong><span>{{ event.actor_name||'System' }} → {{ event.target_name||'Removed account' }}</span></div><time>{{ date(event.created_at) }}</time></article></div></section></div></section>
<div v-if="showForm" class="modal-backdrop"><div class="modal-panel"><div class="modal-panel-header"><div><small>STAFF ACCESS</small><h5>{{ formMode==='password'?'Reset staff password':editing?'Edit staff account':'Add platform staff' }}</h5></div><button class="btn-close" @click="showForm=false"></button></div><form @submit.prevent="save"><template v-if="formMode!=='password'"><label>Full name<input v-model.trim="form.name" class="form-control" required></label><label>Email address<input v-model.trim="form.email" class="form-control" type="email" :disabled="editing" required></label><label>Platform role<select v-model="form.role" class="form-select"><option v-for="role in roles" :key="role" :value="role">{{ roleName(role) }}</option></select></label><label v-if="!editing">Temporary password<input v-model="form.password" class="form-control" type="password" minlength="8" required></label><label v-if="editing" class="switch"><input v-model="form.is_active" type="checkbox"><span>Account is active</span></label></template><template v-else><p class="password-note">Set a temporary password for <strong>{{ editing.name }}</strong>. Existing sessions will be ended.</p><label>Temporary password<input v-model="form.password" class="form-control" type="password" minlength="8" autocomplete="new-password" required></label></template><div class="modal-actions"><button type="button" class="btn btn-outline-secondary" @click="showForm=false">Cancel</button><button class="btn btn-primary" :disabled="saving">{{ saving?'Saving...':formMode==='password'?'Reset password':'Save staff account' }}</button></div></form></div></div></div>
</template>
<style scoped>
