n-top:2rem}.rail nav button,.rail nav a{display:flex;align-items:center;gap:.65rem;padding:.65rem;border:0;border-radius:8px;background:transparent;color:#6e6a73;text-decoration:none;font-size:.72rem;text-align:left}.rail nav .active{background:#eeeaff;color:#6548cf;font-weight:700}.account{margin-top:auto;padding-top:1rem;border-top:1px solid #eee}.account button{margin-top:.7rem;border:0;background:transparent;color:#b34854;font-size:.68rem}.workspace{min-width:0}.workspace>header{position:sticky;top:0;z-index:5;display:flex;align-items:center;justify-content:space-between;padding:1rem;border-bottom:1px solid #e8e7eb;background:rgba(255,255,255,.96)}header h1{margin:.2rem 0 0;font-size:1.15rem}.content{padding:1rem}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem;margin-bottom:1rem}.metrics article{padding:1rem;border:1px solid #e8e6ec;border-radius:11px;background:#fff}.metrics span,.metrics strong{display:block}.metrics span{color:#88848e;font-size:.62rem}.metrics strong{margin-top:.25rem;font-size:1.2rem}.panel{border:1px solid #e7e5ea;border-radius:12px;background:#fff;overflow:hidden}.panel-title{display:flex;align-items:center;justify-content:space-between;padding:1rem}.panel-title h2{margin:0;font-size:.9rem}.panel-title p{margin:.2rem 0 0;color:#8a8690;font-size:.66rem}.panel-title>span,.role,.status{padding:.3rem .55rem;border-radius:99px;background:#eeeaff;color:#6548cf;font-size:.62rem}.panel table{min-width:760px;margin:0;font-size:.7rem}.panel th{color:#918d96;font-size:.62rem;font-weight:600}.person{display:flex;align-items:center;gap:.55rem}.person>span{width:2rem;height:2rem;display:grid;place-items:center;border-radius:50%;background:#eeeaff;color:#6548cf;font-weight:800}.status{background:#e9f8ef;color:#168657}.status.off{background:#fff0f1;color:#c54b58}.actions{display:flex;gap:.3rem;justify-content:flex-end}.actions button{width:1.9rem;height:1.9rem;border:1px solid #e5e2e9;border-radius:6px;background:#fff;color:#625d68}.audit-list article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.7rem;padding:.85rem 1rem;border-top:1px solid #efedf1;font-size:.7rem}.audit-list article>i{width:2rem;height:2rem;display:grid;place-items:center;border-radius:8px;background:#eeeaff;color:#6548cf}.audit-list strong,.audit-list span{display:block}.audit-list strong{text-transform:capitalize}.audit-list span,.audit-list time{color:#8b8791;font-size:.63rem}.modal-panel form{padding-top:1rem}.switch{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center}.switch input{width:1rem;height:1rem}@media(min-width:760px){.platform-login{grid-template-columns:minmax(400px,.8fr) minmax(450px,1.2fr)}.platform-login>section{padding:clamp(2rem,6vw,5rem)}.platform-login aside{display:flex;flex-direction:column;justify-content:center;padding:clamp(3rem,8vw,8rem);background:linear-gradient(145deg,#292231,#513a91);color:#fff}.platform-login aside i{font-size:2rem}.platform-login aside h2{max-width:650px;font-size:clamp(2.5rem,5vw,4.5rem);letter-spacing:-.055em}.platform-login aside p{max-width:560px;color:#d5cfe2;line-height:1.7}.rail{display:flex}.workspace{margin-left:220px}.workspace>header,.content{padding:1.25rem 1.5rem}}
.password-note{padding:.75rem;border-radius:8px;background:#fff5dd;color:#79550f;font-size:.7rem}
</style>
